import React from "react";
import { Link } from "react-router-dom";

const Navbar = ({ role }) => {
  return (
    <nav style={{ padding: "10px 20px", backgroundColor: "#333", color: "#fff", display: "flex", gap: "20px" }}>
      <Link to="/" style={{ color: "#fff", textDecoration: "none" }}>Dashboard</Link>
      {role === "admin" && (
        <>
          <Link to="/logs" style={{ color: "#fff", textDecoration: "none" }}>Logs</Link>
          <Link to="/analytics" style={{ color: "#fff", textDecoration: "none" }}>Analytics</Link>
        </>
      )}
    </nav>
  );
};

export default Navbar;
